# Builds the Zenodo archive: the full project folder, as on GitHub (including
# the website in docs/), plus the
# files that are too large for GitHub or generated by the pipeline (fitted
# models, cached online data and slow steps, intermediate objects, figures,
# tables and reports). Unzipped, it reproduces all results without refitting
# the models or querying online services.
#
# Not included: third-party input data in data/ (downloaded automatically
# from pinned versions; see data/README.md). The cached IUCN Red List
# categories (species name and category only, Red List version 2025-2) are
# included, with attribution in data/README.md.
#
# Run after a complete run of run_all.R and renv::snapshot().

project_dir <- here::here()
archive_dir <- file.path(project_dir, "archive")
dir.create(archive_dir, showWarnings = FALSE)

old_wd <- setwd(project_dir)
on.exit(setwd(old_wd), add = TRUE)

all_files <- list.files(".", recursive = TRUE, all.files = TRUE, no.. = TRUE)
all_files <- sub("^\\./", "", all_files)

keep <- all_files[
  # Code, documentation, the reference databases and the website
  grepl("^(R/|0_Get_reference_data/|data/CRABS/|docs/)", all_files) |
  all_files %in% c("data/README.md", "README.md", "LICENSE", "CITATION.cff",
                   "Pipeline.Rproj", "run_all.R", "make_archive.R",
                   "renv.lock", ".Rprofile", "renv/activate.R", ".gitignore") |
  grepl("^[0-9]_.*\\.Rmd$", all_files) |
  # Generated outputs
  grepl("^output/", all_files)
]


zipfile <- file.path(archive_dir, "Luypaert_et_al_2026_pipeline.zip")
if (file.exists(zipfile)) file.remove(zipfile)

# zip::zip needs no external zip program (unlike utils::zip on Windows)
zip::zip(zipfile, files = keep, mode = "mirror")

message(sprintf("%d files, %.1f MB", length(keep), file.size(zipfile) / 1e6))
message("MD5: ", unname(tools::md5sum(zipfile)))

# Files per top-level folder, as a check
print(table(sub("/.*", "", keep)))
